"use strict";(globalThis.webpackChunkgrc||=[]).push([[23682],{37186(e){e.exports=JSON.parse('{"citeKey":"he2014s4dcache","slug":"he-2014-s4d-cache-3fc9","title":"S4D-Cache: Smart Selective SSD Cache for Parallel I/O Systems","authors":["S. He","X.-H. Sun","B. Feng"],"venue":"International Conference on Distributed Computing Systems (ICDCS), Madrid, Spain","type":"Conference","entryType":"inproceedings","date":"June, 2014","year":2014,"era":"iit","month":6,"doi":"10.1109/icdcs.2014.59","abstract":"Parallel file systems (PFS) are widely-used in mod- ern computing systems to mask the ever-increasing performance gap between computing and data access. PFSs favor large requests, and do not work well for small requests, especially small random requests. Newer Solid State Drives (SSD) have excellent performance on small random data accesses, but also incur a high monetary cost. In this study, we propose a hybrid architecture named the Smart Selective SSD Cache (S4D-Cache), which employs a small set of SSD-based file servers as a selective cache of conventional HDD-based file servers. A novel scheme is introduced to identify performance-critical data, and conduct selective cache admission to fully utilize the hybrid architecture in terms of data-access parallelism and randomness. We have implemented an S4D-Cache under the MPI-IO and PVFS2 parallel file system. Our experiments show that S4D-Cache can significantly improve I/O throughput, and is a promising approach for parallel applications.","hasAbstract":true,"lede":"In this study, we propose a hybrid architecture named the Smart Selective SSD Cache (S4D-Cache).","links":{"pdf":"https://grc.iit.edu/papers/2014/he-2014-s4d-cache-3fc9.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);